__device__ __forceinline__ int observe_binary(float x,const Entry*d,int count){uint32_t bits=__float_as_uint(__uint_as_float(tf(x*0.125f))*0x1p-30f);int lo=0,hi=count;while(lo<hi){int mid=(lo+hi)/2;if(d[mid].bits<bits)lo=mid+1;else hi=mid;}return lo<count&&d[lo].bits==bits?d[lo].target:-1;}
